# Generated by Claudian.
"""Skill: quit/close a macOS application."""

import re

from ai.response_generator import ResponseGenerator
from automation.app_control import close_app
from multitasking.async_executor import run_in_thread
from skills._base import Skill, SkillMatch, SkillResult
from skills.open_app import _clean_captured_app

_PATTERN = re.compile(
    r"(?:close|quit|exit|kill|terminate|force\s+quit)\s+(?:the\s+)?(.+)"
)


class CloseAppSkill(Skill):
    name = "close_app"
    description = "Quit a macOS application"
    priority = 30

    def __init__(self):
        self._responses = ResponseGenerator()

    def match(self, text: str) -> SkillMatch | None:
        m = _PATTERN.search(text.lower())
        if not m:
            return None
        app = _clean_captured_app(m.group(1))
        if not app or "jarvis" in app:
            # "quit jarvis" belongs to shutdown_jarvis
            return None
        return SkillMatch(confidence=0.92, entities={"app_name": app})

    async def run(self, text: str, entities: dict) -> SkillResult:
        app = entities.get("app_name", text)
        status, resolved = await run_in_thread(close_app, app)

        if status == "closed":
            return SkillResult(text=self._responses.app_closed(resolved))
        if status == "not_running":
            # Saying "closed" here would be a lie, and the user would think
            # something happened when nothing did.
            return SkillResult(text=f"{resolved} wasn't running.")
        return SkillResult(
            text=f"I couldn't close {resolved} — it's still running."
        )
